class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):  # viz:lengths
            return False
        counts = Counter(s)  # viz:count
        for ch in t:
            counts[ch] -= 1  # viz:use
            if counts[ch] < 0:
                return False  # viz:extra
        return True  # viz:done
